def breakPalindrome(palindrome):
    if len(palindrome) == 1:
        return ""

    for i in range(len(palindrome) // 2):
        if palindrome[i] != 'a':
            return palindrome[:i] + 'a' + palindrome[i+1:]

    return palindrome[:-1] + 'b'

# Example usage:
# print(breakPalindrome("abccba"))  # Output: "aaccba"
# print(breakPalindrome("a"))       # Output: ""
